class ChipKategori extends StatelessWidget {
  const ChipKategori({super.key, required this.terpilih, required this.onPilih});
  final String terpilih;
  final ValueChanged<String> onPilih;

  static const kategori = ['Semua', 'Kopi', 'Non-kopi', 'Roti', 'Promo'];

  @override
  Widget build(BuildContext context) {
    return SizedBox(
      height: 48,
      child: ListView.separated(
        scrollDirection: Axis.horizontal,
        padding: const EdgeInsets.symmetric(horizontal: 16),
        itemCount: kategori.length,
        separatorBuilder: (_, __) => const SizedBox(width: 8),
        itemBuilder: (_, i) => ChoiceChip(
          label: Text(kategori[i]),
          selected: kategori[i] == terpilih,
          onSelected: (_) => onPilih(kategori[i]),
        ),
      ),
    );
  }
}

Widget fotoDenganDiskon(String foto, int persen) {
  return Stack(
    children: [
      AspectRatio(
        aspectRatio: 1,
        child: ClipRRect(
          borderRadius: BorderRadius.circular(12),
          child: Image.asset(foto, fit: BoxFit.cover),
        ),
      ),
      Positioned(
        top: 8,
        left: 8,
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 8, vertical: 4),
          decoration: BoxDecoration(color: Colors.red.shade700, borderRadius: BorderRadius.circular(8)),
          child: Text('-$persen%', style: const TextStyle(color: Colors.white, fontWeight: FontWeight.w700)),
        ),
      ),
    ],
  );
}

@Composable
fun KartuProduk(p: Produk, onTambah: () -> Unit) {
    Card(shape = RoundedCornerShape(12.dp)) {
        Box {
            AsyncImage(
                model = p.fotoUrl, contentDescription = p.nama,
                contentScale = ContentScale.Crop,
                modifier = Modifier.fillMaxWidth().aspectRatio(1f)
            )
            if (p.diskon > 0) {
                Text(
                    "-${p.diskon}%",
                    color = Color.White,
                    modifier = Modifier
                        .align(Alignment.TopStart)
                        .padding(8.dp)
                        .background(Color(0xFFC62828), RoundedCornerShape(8.dp))
                        .padding(horizontal = 8.dp, vertical = 4.dp)
                )
            }
        }
        Text(p.nama, maxLines = 2, overflow = TextOverflow.Ellipsis, modifier = Modifier.padding(12.dp))
    }
}

@Composable
fun ChipKategori(kategori: List<String>, terpilih: String, onPilih: (String) -> Unit) {
    LazyRow(
        contentPadding = PaddingValues(horizontal = 16.dp),
        horizontalArrangement = Arrangement.spacedBy(8.dp)
    ) {
        items(kategori) { k ->
            FilterChip(
                selected = k == terpilih,
                onClick = { onPilih(k) },
                label = { Text(k) }
            )
        }
    }
}

